<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\Model; use Pterodactyl\Models\User; use Illuminate\Database\Eloquent\Relations\BelongsTo; class StaffMessage extends Model { public const RESOURCE_NAME = 'staff_message'; public const MAX_LENGTH = 2000; public const MAX_PER_REQUEST = 500; protected $table = 'dezerx_staff_messages'; protected $guarded = ['id']; public $timestamps = false; protected $casts = [ 'request_id' => 'int', 'user_id' => 'int', 'created_at' => 'datetime', ]; public static array $validationRules = [ 'request_id' => 'required|int', 'body' => 'required|string|max:2000', ]; public function request(): BelongsTo { return $this->belongsTo(StaffRequest::class, 'request_id'); } public function author(): BelongsTo { return $this->belongsTo(User::class, 'user_id'); } } 